cat > /usr/local/bin/openclaw-approve-browser <<''EOF''
#!/usr/bin/env bash
set -euo pipefail

if [ "$(id -un)" != "{5}" ]; then
  exec sudo -u {5} /usr/local/bin/openclaw-approve-browser "$@"
fi

if [ -r /etc/openclaw/openclaw.env ]; then
	set -a
	. /etc/openclaw/openclaw.env
	set +a
	PATH="/home/{5}/.openclaw/tools/node/bin:/home/{5}/.openclaw/bin:$PATH"
	export PATH
fi

# Prefer direct Node access to the installed device-pairing module. The
# `openclaw` CLI cold-starts in ~27s and `openclaw devices list` additionally
# waits ~45s trying to reach the gateway before falling back to local state,
# which makes the retry loop take minutes. Calling listDevicePairing /
# approveDevicePairing directly runs in ~50ms.

OPENCLAW_STATE_DIR="${{OPENCLAW_STATE_DIR:-$HOME/.openclaw}}"
OPENCLAW_NODE_BIN="$OPENCLAW_STATE_DIR/tools/node/bin/node"
OPENCLAW_DIST_DIR="$OPENCLAW_STATE_DIR/lib/node_modules/openclaw/dist"
OPENCLAW_PAIRING_MODULE="$(find "$OPENCLAW_DIST_DIR" -maxdepth 1 -name ''device-pairing-*.js'' 2>/dev/null | head -n 1)"

if [ ! -x "$OPENCLAW_NODE_BIN" ]; then
	echo "OpenClaw Node runtime was not found at $OPENCLAW_NODE_BIN" >&2
	exit 1
fi

if [ -z "$OPENCLAW_PAIRING_MODULE" ]; then
	echo "OpenClaw device pairing module was not found under $OPENCLAW_DIST_DIR" >&2
	exit 1
fi

list_browser_request_id() {{
	"$OPENCLAW_NODE_BIN" --input-type=module - "$OPENCLAW_PAIRING_MODULE" "$OPENCLAW_STATE_DIR" <<''NODE_LIST''
const [modulePath, stateDir] = process.argv.slice(2);
const url = await import("node:url");
const mod = await import(url.pathToFileURL(modulePath).href);
const listPairing = Object.values(mod).find(
	(value) => typeof value === "function" && value.name === "listDevicePairing",
);
if (!listPairing) {{
	throw new Error("listDevicePairing export was not found in the installed OpenClaw device pairing module.");
}}
const list = await listPairing(stateDir);
const pending = (list.pending || []).filter((item) => {{
	const clientId = String(item?.clientId || "");
	const clientMode = String(item?.clientMode || "");
	return clientId === "openclaw-control-ui" || clientMode === "webchat" || clientMode === "browser";
}});
pending.sort((left, right) => {{
	const leftTs = Number(left?.ts || left?.createdAtMs || 0);
	const rightTs = Number(right?.ts || right?.createdAtMs || 0);
	return rightTs - leftTs;
}});
const latest = pending[0];
if (!latest || !latest.requestId) {{
	process.exit(2);
}}
process.stdout.write(String(latest.requestId));
NODE_LIST
}}

approve_browser_request() {{
	local request_id="$1"
	"$OPENCLAW_NODE_BIN" --input-type=module - "$OPENCLAW_PAIRING_MODULE" "$OPENCLAW_STATE_DIR" "$request_id" <<''NODE_APPROVE''
const [modulePath, stateDir, requestId] = process.argv.slice(2);
const url = await import("node:url");
const mod = await import(url.pathToFileURL(modulePath).href);
const listPairing = Object.values(mod).find(
	(value) => typeof value === "function" && value.name === "listDevicePairing",
);
const approvePairing = Object.values(mod).find(
	(value) => typeof value === "function" && value.name === "approveDevicePairing",
);
if (!listPairing || !approvePairing) {{
	throw new Error("listDevicePairing / approveDevicePairing exports were not found in the installed OpenClaw device pairing module.");
}}
const list = await listPairing(stateDir);
const pending = (list.pending || []).find((item) => String(item?.requestId || "") === requestId);
if (!pending) {{
	process.stderr.write(`Pending device pairing request not found: ${{requestId}}\n`);
	process.exit(3);
}}
// Approving locally as the trusted host process: grant exactly the scopes the
// client asked for. Without callerScopes, requests carrying operator scopes
// are rejected with {{ status: "forbidden", reason: "caller-scopes-required" }}.
const callerScopes = Array.isArray(pending.scopes) ? [...pending.scopes] : [];
const approved = await approvePairing(requestId, {{ callerScopes }}, stateDir);
if (!approved) {{
	process.stderr.write(`Unknown device pairing request: ${{requestId}}\n`);
	process.exit(3);
}}
if (approved.status === "forbidden") {{
	process.stderr.write(
		`Pairing approval forbidden: reason=${{approved.reason || "unknown"}}` +
			(approved.scope ? ` scope=${{approved.scope}}` : "") +
			(approved.role ? ` role=${{approved.role}}` : "") +
			"\n",
	);
	process.exit(5);
}}
const deviceId = String(approved?.device?.deviceId || approved?.deviceId || "").trim();
if (!deviceId) {{
	process.stderr.write(
		`Approved pairing response did not include a deviceId. Raw response: ${{JSON.stringify(approved)}}\n`,
	);
	process.exit(4);
}}
process.stdout.write(JSON.stringify({{ requestId, deviceId }}) + "\n");
NODE_APPROVE
}}

request_id=""
attempt=1
while [ "$attempt" -le 3 ]; do
	set +e
	pairing_output="$(list_browser_request_id 2>&1)"
	status=$?
	set -e

	request_id="$(printf "%s\n" "$pairing_output" | tail -n 1 | tr -d ''\r'')"

	if [ "$status" -eq 0 ] && [ -n "$request_id" ]; then
		break
	fi

	if [ "$status" -ne 2 ]; then
		printf "%s\n" "$pairing_output" >&2
		exit "$status"
	fi

	if [ "$attempt" -eq 3 ]; then
		echo "No pending browser pairing requests. Keep the dashboard page open on the pairing screen, wait a few seconds, and try again." >&2
		exit 0
	fi

	sleep 2
	attempt=$((attempt + 1))
done

echo "Approving browser pairing request: $request_id" >&2
approve_browser_request "$request_id"
EOF
chmod 755 /usr/local/bin/openclaw-approve-browser
cat > /usr/local/bin/openclaw-approve-teams-pairing <<''EOF''
#!/usr/bin/env bash
set -euo pipefail

pairing_code=""
if [ "$#" -gt 0 ]; then
  pairing_code="$1"
fi

code="$pairing_code"
if [ -z "$code" ]; then
  if ! command -v python3 >/dev/null 2>&1; then
    echo "python3 is required when pairing code is not passed explicitly." >&2
    exit 1
  fi

  if [ "$(id -un)" = "{5}" ]; then
    pairing_json=$(bash -lc ''exec /usr/local/bin/openclaw pairing list msteams --json'')
  else
    pairing_json=$(sudo -u {5} bash -lc ''exec /usr/local/bin/openclaw pairing list msteams --json'')
