queue_openclaw_config_string() {{
  local key="$1"
  local value="$2"
  local enc
  enc=$(printf ''%s'' "$value" | base64 -w 0)
  printf ''S\t%s\t%s\n'' "$key" "$enc" >> "$OPENCLAW_CONFIG_BATCH_FILE"
}}

queue_openclaw_config_json() {{
  local key="$1"
  local value="$2"
  local enc
  enc=$(printf ''%s'' "$value" | base64 -w 0)
  printf ''J\t%s\t%s\n'' "$key" "$enc" >> "$OPENCLAW_CONFIG_BATCH_FILE"
}}

apply_openclaw_config_batch() {{
  sudo -u {5} env \
    HOME="/home/{5}" \
    BATCH_PATH="$OPENCLAW_CONFIG_BATCH_FILE" \
    CONFIG_PATH="/home/{5}/.openclaw/openclaw.json" \
    python3 - <<''PY''
import base64
import json
import os

cfg_path = os.environ["CONFIG_PATH"]
batch_path = os.environ["BATCH_PATH"]

with open(cfg_path, "r", encoding="utf-8") as fh:
  cfg = json.load(fh)

def set_path(root, dotted, value):
  parts = dotted.split(".")
  cur = root
  for part in parts[:-1]:
    nxt = cur.get(part)
    if not isinstance(nxt, dict):
      nxt = {{}}
      cur[part] = nxt
    cur = nxt
  cur[parts[-1]] = value

with open(batch_path, "r", encoding="utf-8") as fh:
  for line in fh:
    line = line.rstrip("\n")
    if not line:
      continue
    kind, key, enc = line.split("\t", 2)
    raw = base64.b64decode(enc).decode("utf-8")
    value = json.loads(raw) if kind == "J" else raw
    set_path(cfg, key, value)

tmp = cfg_path + ".tmp"
with open(tmp, "w", encoding="utf-8") as fh:
  json.dump(cfg, fh, indent=2, ensure_ascii=False)
  fh.write("\n")
os.replace(tmp, cfg_path)
PY
  rm -f "$OPENCLAW_CONFIG_BATCH_FILE"
}}

write_openclaw_auth_profile() {{
  local profile_id="$1"
  local profile_json="$2"
  local auth_store_path="/home/{5}/.openclaw/agents/main/agent/auth-profiles.json"

  install -d -o {5} -g {5} "$(dirname "$auth_store_path")"
  sudo -u {5} env \
    HOME="/home/{5}" \
    PROFILE_ID="$profile_id" \
    PROFILE_JSON="$profile_json" \
    AUTH_STORE_PATH="$auth_store_path" \
    python3 - <<''PY''
import json
import os
from pathlib import Path

path = Path(os.environ["AUTH_STORE_PATH"])
if path.exists():
  try:
    store = json.loads(path.read_text(encoding="utf-8"))
  except json.JSONDecodeError:
    store = {{"version": 1, "profiles": {{}}}}
else:
  store = {{"version": 1, "profiles": {{}}}}

if not isinstance(store, dict):
  store = {{"version": 1, "profiles": {{}}}}

store["version"] = 1
profiles = store.get("profiles")
if not isinstance(profiles, dict):
  profiles = {{}}
  store["profiles"] = profiles

profiles[os.environ["PROFILE_ID"]] = json.loads(os.environ["PROFILE_JSON"])
path.write_text(json.dumps(store, ensure_ascii=True, indent=2) + "\n", encoding="utf-8")
PY
  chmod 600 "$auth_store_path"
}}

